 private void navigate(int target){page=target;String[] icons={TapeIcon.MIC,TapeIcon.LIBRARY,TapeIcon.MAP};for(int n=0;n<navigation.size();n++){boolean selected=n==page||page==3&&n==returnPage;Button tab=navigation.get(n);int color=selected?ORANGE:MUTED;tab.setTextColor(color);tab.setCompoundDrawablesWithIntrinsicBounds(null,TapeTheme.icon(this,icons[n],color,false),null,null);tab.setBackground(TapeTheme.ripple(this,selected?TapeTheme.SOFT:android.graphics.Color.TRANSPARENT,14));}recordingScroll.setVisibility(page==0?View.VISIBLE:View.GONE);libraryFrame.setVisibility(page==1?View.VISIBLE:View.GONE);mapPage.setVisibility(page==2?View.VISIBLE:View.GONE);detailScroll.setVisibility(page==3?View.VISIBLE:View.GONE);if(page==2)updateMap();handler.removeCallbacks(holdSpeed);if(holdingSpeed){holdingSpeed=false;applySpeed(playbackSpeed);}if(page!=0)tape.state(false,false);if(page!=3&&playerTape!=null)playerTape.state(false,false);}
 private JSONObject find(String key){for(JSONObject j:snapshot)if(key.equals(j.optString("key"))&&!removing.contains(key))return j;return null;}
 private ArrayList<JSONObject> filtered(){ArrayList<JSONObject> out=new ArrayList<>();for(JSONObject j:snapshot)if(!removing.contains(j.optString("key"))&&LibraryRules.matches(j.optString("title"),j.optString("source"),j.optLong("startedAt"),j.optLong("importedAt"),j.optBoolean("favorite"),query,favoritesOnly,dateFrom,dateUntil))out.add(j);return out;}
 private boolean located(JSONObject j){JSONObject p=j.optJSONObject("location");return p!=null&&LibraryRules.valid(p.optDouble("latitude",Double.NaN),p.optDouble("longitude",Double.NaN));}
 private void renderList(){if(destroyed||adapter==null)return;if(loading){reloadWanted=true;return;}loading=true;files.execute(()->{ArrayList<JSONObject> next=repo.list();handler.post(()->{if(destroyed)return;snapshot=next;loading=false;applySnapshot();RecordingPlaces.resolve(this,repo,next);if(reloadWanted){reloadWanted=false;renderList();}});});}
 private void applySnapshot(){if(adapter==null||mapFavorite==null)return;ArrayList<JSONObject> items=filtered();adapter.submit(items,player!=null&&playerReady&&player.isPlaying()?playingKey:"");libraryCount.setText(items.size()+" 段录音  ·  左滑删除");libraryTime.setText(dateLabel);mapTime.setText(dateLabel);for(Button b:new Button[]{libraryFavorite,mapFavorite})TapeTheme.setIcon(b,TapeIcon.STAR,favoritesOnly?"查看全部录音":"只看收藏",favoritesOnly?TapeTheme.GOLD:MUTED,favoritesOnly);updateMap();if(page==3){JSONObject j=find(detailKey);if(j!=null&&!seeking&&!holdingSpeed)renderDetail(j);}updateMini();}
 private void updateMini(){if(adapter!=null)adapter.submit(filtered(),player!=null&&playerReady&&player.isPlaying()?playingKey:"");if(page==2&&!selectedKey.isEmpty()){JSONObject selected=find(selectedKey);if(selected!=null)showMapRecording(selected);}if(miniPlay!=null)TapeTheme.setIcon(miniPlay,player!=null&&playerReady&&player.isPlaying()?TapeIcon.PAUSE:TapeIcon.PLAY,"播放或暂停",INK,false);if(miniPlayer==null)return;miniPlayer.setVisibility(playingKey.isEmpty()?View.GONE:View.VISIBLE);JSONObject j=find(playingKey);miniTitle.setText(j==null?"正在播放":j.optString("title"));}
 private void favorite(JSONObject j){String key=j.optString("key");files.execute(()->{try{repo.favorite(key,!j.optBoolean("favorite"));handler.post(()->{if(!destroyed){TapeService.libraryVersion++;renderList();}});}catch(Exception e){handler.post(()->toast("收藏未保存，请重试"));}});}
 private void deleteRecording(JSONObject j){String key=j.optString("key");if(removing.contains(key))return;if(key.equals(playingKey))stopPlayback();if(!pendingUndo.isEmpty())finishPendingDelete();removing.add(key);if(key.equals(selectedKey)){selectedKey="";mapSelection.removeAllViews();}if(page==3&&key.equals(detailKey))navigate(1);applySnapshot();files.execute(()->{try{repo.remove(key);handler.post(()->{if(destroyed){filesFinish(key);return;}removing.remove(key);TapeService.libraryVersion++;if(!pendingUndo.isEmpty())finishPendingDelete();pendingUndo=key;undoBar.setVisibility(View.VISIBLE);finishUndo=this::finishPendingDelete;undoDeadline=SystemClock.elapsedRealtime()+5000;undoText.setText("录音已删除 · 5 秒");handler.postDelayed(finishUndo,5000);renderList();});}catch(Exception e){handler.post(()->{if(!destroyed){removing.remove(key);toast("删除未完成，请重试");renderList();}});}});}
 private void filesFinish(String key){try{repo.finishRemove(key);}catch(IOException ignored){}}
 private void finishPendingDelete(){if(finishUndo!=null)handler.removeCallbacks(finishUndo);String key=pendingUndo;pendingUndo="";undoBar.setVisibility(View.GONE);if(!key.isEmpty()&&!files.isShutdown())files.execute(()->filesFinish(key));}
 private void undoDelete(){String key=pendingUndo;if(key.isEmpty())return;if(finishUndo!=null)handler.removeCallbacks(finishUndo);pendingUndo="";undoBar.setVisibility(View.GONE);files.execute(()->{try{repo.undoRemove(key);handler.post(()->{if(!destroyed){TapeService.libraryVersion++;renderList();}});}catch(Exception e){handler.post(()->{toast("撤销未完成，请检查录音库");TapeService.libraryVersion++;renderList();});}});}
 private void toast(String value){if(!destroyed)Toast.makeText(this,value,Toast.LENGTH_LONG).show();}
 private void recordActions(JSONObject j){String[] choices={"修改名称","分享录音",j.optBoolean("favorite")?"取消收藏":"收藏录音","删除手机录音"};new AlertDialog.Builder(this).setTitle(j.optString("title")).setItems(choices,(d,n)->{if(n==0)rename(j.optString("key"),j.optString("title"));else if(n==1)share(j.optString("key"),located(j));else if(n==2)favorite(j);else deleteRecording(j);}).show();}
 private void showDetail(JSONObject j){returnPage=page==3?returnPage:page;detailKey=j.optString("key");renderDetail(j);navigate(3);}
 private String description(JSONObject j){long t=j.optLong("startedAt");if(t<=0)t=j.optLong("importedAt");return new SimpleDateFormat("yyyy.MM.dd  HH:mm",Locale.getDefault()).format(new Date(t))+"  ·  "+("phone".equals(j.optString("source"))?"手机录音":"灵感磁带")+(j.optLong("startedAt")<=0?" · 导入":"");}
