 private void updateMap(){if(map==null||mapSelection==null)return;ArrayList<JSONObject> points=new ArrayList<>();ArrayList<JSONObject> items=filtered();for(JSONObject j:items)if(located(j)&&(!region.isChecked()||map.contains(j)))points.add(j);located.clear();located.addAll(points);map.points(points);mapCount.setText(points.size()+" 段有位置  /  "+items.size()+" 段符合筛选"+(query.isEmpty()?"":" · "+query));if(!selectedKey.isEmpty()){JSONObject selected=null;for(JSONObject j:points)if(selectedKey.equals(j.optString("key")))selected=j;if(selected==null){selectedKey="";mapSelection.removeAllViews();}else showMapRecording(selected);}}
 private void showMapRecording(JSONObject j){selectedKey=j.optString("key");mapSelection.removeAllViews();LinearLayout info=new LinearLayout(this);info.setGravity(Gravity.CENTER_VERTICAL);info.setPadding(dp(12),dp(8),dp(4),dp(8));info.setBackground(background(TapeTheme.PANEL,14));TextView name=heading(j.optString("title"),14);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);name.setOnClickListener(v->showDetail(j));info.addView(name,new LinearLayout.LayoutParams(0,-2,1));info.addView(icon(playingKey.equals(selectedKey)&&playerReady&&player.isPlaying()?TapeIcon.PAUSE:TapeIcon.PLAY,playingKey.equals(selectedKey)&&playerReady&&player.isPlaying()?"暂停":"播放录音",()->play(j.optString("key"))),new LinearLayout.LayoutParams(dp(48),dp(48)));info.addView(icon(TapeIcon.CHEVRON,"录音详情",()->showDetail(j)),new LinearLayout.LayoutParams(dp(40),dp(48)));add(mapSelection,info,5);}
 private void mapResults(){if(located.isEmpty()){toast("这个范围内还没有录音位置");return;}ArrayList<JSONObject> points=new ArrayList<>(located);String[] names=new String[points.size()];for(int i=0;i<names.length;i++)names[i]=points.get(i).optString("title");new AlertDialog.Builder(this).setTitle("地图中的录音").setItems(names,(d,n)->{map.focus(points.get(n));showMapRecording(points.get(n));}).show();}
 private void externalMap(JSONObject p){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("geo:"+p.optDouble("latitude")+","+p.optDouble("longitude")+"?q="+p.optDouble("latitude")+","+p.optDouble("longitude"))));}catch(Exception e){toast("未安装可打开位置的地图应用");}}
 private final Runnable holdSpeed=()->{if(player!=null&&playerReady&&player.isPlaying()){holdingSpeed=true;applySpeed(2f);}};
 private String speedLabel(){return String.format(Locale.US,"%s×",playbackSpeed==1?"1":Float.toString(playbackSpeed));}
 private void chooseSpeed(){String[] names={"1×","1.25×","1.5×","1.75×","2×"};float[] values={1,1.25f,1.5f,1.75f,2};new AlertDialog.Builder(this).setTitle("播放速度").setItems(names,(d,n)->{playbackSpeed=values[n];applySpeed(playbackSpeed);if(speedButton!=null)speedButton.setText(speedLabel());}).show();}
 private void applySpeed(float speed){if(player!=null&&playerReady){boolean running=player.isPlaying();try{player.setPlaybackParams(new android.media.PlaybackParams().setSpeed(speed).setPitch(1));if(!running)player.pause();}catch(IllegalArgumentException e){toast("这段录音暂不支持此倍速");}}}
 private void seekBy(int amount){if(player!=null&&playerReady)player.seekTo(Math.max(0,Math.min(player.getDuration(),player.getCurrentPosition()+amount)));}
 private void stopPlayback(){handler.removeCallbacks(holdSpeed);holdingSpeed=false;if(player!=null){player.release();player=null;}playerReady=false;playingKey="";applySnapshot();}
 private void play(String key){if(TapeService.phoneRecording){toast("请先结束手机录音再播放");return;}if(key.isEmpty())return;if(key.equals(playingKey)){if(playerReady){if(player.isPlaying())player.pause();else player.start();updateMini();}return;}stopPlayback();try{MediaPlayer next=new MediaPlayer();player=next;playingKey=key;next.setDataSource(repo.wav(key).getPath());next.setOnPreparedListener(mp->{if(player==mp&&!destroyed){playerReady=true;mp.start();applySpeed(playbackSpeed);updateMini();}});next.setOnCompletionListener(mp->{if(player==mp){mp.pause();mp.seekTo(0);updateMini();}});next.setOnErrorListener((mp,what,extra)->{if(player==mp){stopPlayback();toast("无法播放这段录音");}return true;});next.prepareAsync();applySnapshot();}catch(Exception e){stopPlayback();toast("播放失败，请重试");}}
 private void rename(String key,String old){EditText input=new EditText(this);input.setText(old);input.setSingleLine(false);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(120)});new AlertDialog.Builder(this).setTitle("给这段灵感命名").setView(input).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{String title=input.getText().toString();files.execute(()->{try{repo.rename(key,title);handler.post(()->{if(!destroyed){TapeService.libraryVersion++;renderList();}});}catch(Exception e){handler.post(()->toast("名称未保存，请重试"));}});}).show();}
 private static String time(long seconds){return String.format(Locale.getDefault(),"%02d:%02d",seconds/60,seconds%60);}
 private void mapConsent(){boolean on=getSharedPreferences("settings",0).getBoolean("osmConsentV1",false);new AlertDialog.Builder(this).setTitle("在线地图与隐私").setMessage("开启后从 OpenStreetMap 获取当前可见区域的底图；服务方可获知 IP 和浏览区域。本应用不上传音频、标题和标记资料。底图依赖网络，暂不可用时仍保留本机录音标记和播放。地图数据 © OpenStreetMap contributors。")
 .setNegativeButton(on?"停止联网":"暂不开启",(d,w)->{if(on){getSharedPreferences("settings",0).edit().putBoolean("osmConsentV1",false).apply();map.online(false);}}).setNeutralButton("隐私与署名",(d,w)->privacy()).setPositiveButton("开启底图",(d,w)->{getSharedPreferences("settings",0).edit().putBoolean("osmConsentV1",true).apply();map.online(true);}).show();}
 private void privacy(){new AlertDialog.Builder(this).setTitle("灵感磁带 · 隐私与署名").setMessage("录音、名称、收藏和可选的录音起点位置保存在 App 私有目录。麦克风用于你主动开始的手机录音；蓝牙用于接收设备录音。卸载会删除本机录音，建议先导出。定位可选，不记录行程轨迹。设备地点显示需另外开启：系统地址服务可能联网解析当前位置，通过蓝牙显示道路名，录音库地点名称保存在位置资料中。删除后有 5 秒撤销倒计时；最终删除音频和位置资料，仅保留防止重复补传的文件识别凭据。分享默认只含音频，附带位置资料需另外选择。\n\n开启在线地图后，仅向 OpenStreetMap 请求当前可见图块，对方可获知 IP 和浏览区域。不上传录音文件、名称或标记资料。可停止底图联网；没有云账号或云端录音备份。地图数据 © OpenStreetMap contributors，按 OpenStreetMap 许可署名。")
 .setNegativeButton("返回",(d,w)->mapConsent()).setPositiveButton("地图许可",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.openstreetmap.org/copyright")));}catch(Exception e){Toast.makeText(this,"请访问 openstreetmap.org/copyright",Toast.LENGTH_LONG).show();}}).show();}
 private void chooseDate(){new AlertDialog.Builder(this).setTitle("按时间筛选").setItems(new String[]{"全部时间","今天","最近 7 天","最近 30 天","自选日期范围"},(d,n)->{
  if(n==4){pickDate(false,0);return;}dateUntil=Long.MAX_VALUE;dateFrom=0;dateLabel=new String[]{"全部时间","今天","最近 7 天","最近 30 天"}[n];if(n>0){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);Calendar tomorrow=(Calendar)c.clone();tomorrow.add(Calendar.DAY_OF_YEAR,1);dateUntil=tomorrow.getTimeInMillis();c.add(Calendar.DAY_OF_YEAR,n==1?0:n==2?-6:-29);dateFrom=c.getTimeInMillis();}applySnapshot();}).show();}
 private void pickDate(boolean end,long start){Calendar c=Calendar.getInstance();DatePickerDialog dialog=new DatePickerDialog(this,(v,y,m,d)->{Calendar chosen=Calendar.getInstance();chosen.clear();chosen.set(y,m,d);if(!end)pickDate(true,chosen.getTimeInMillis());else{chosen.add(Calendar.DAY_OF_YEAR,1);if(chosen.getTimeInMillis()<=start){Toast.makeText(this,"结束日期不能早于开始日期",Toast.LENGTH_LONG).show();return;}dateFrom=start;dateUntil=chosen.getTimeInMillis();SimpleDateFormat fmt=new SimpleDateFormat("MM/dd",Locale.getDefault());dateLabel=fmt.format(new Date(start))+"–"+fmt.format(new Date(dateUntil-1));applySnapshot();}},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH));dialog.setTitle(end?"选择结束日期（含当天）":"选择开始日期");dialog.show();}
 private String[] bluetoothPermissions(){if(Build.VERSION.SDK_INT>=31)return new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT};return new String[]{Manifest.permission.ACCESS_FINE_LOCATION};}
 private void permissions(String[] names,Runnable next){locationRequest=Arrays.asList(names).contains(Manifest.permission.ACCESS_COARSE_LOCATION);ArrayList<String> needed=new ArrayList<>();for(String s:names)if(checkSelfPermission(s)!=PackageManager.PERMISSION_GRANTED)needed.add(s);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)needed.add(Manifest.permission.POST_NOTIFICATIONS);if(needed.isEmpty()){next.run();return;}afterPermission=next;requestPermissions(needed.toArray(new String[0]),9);}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);Runnable next=afterPermission;afterPermission=null;if(request==9&&next!=null){if(results.length==0)return;boolean denied=false;for(int i=0;i<permissions.length;i++)if(!permissions[i].equals(Manifest.permission.POST_NOTIFICATIONS)&&(!permissions[i].equals(Manifest.permission.ACCESS_FINE_LOCATION)||!locationRequest)&&results[i]!=PackageManager.PERMISSION_GRANTED)denied=true;
   if(denied){Toast.makeText(this,"权限未授予；设备仍可离线录音",Toast.LENGTH_LONG).show();if(!locationAllowed())gps.setChecked(false);return;}next.run();}}
 private boolean locationAllowed(){return checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 private void service(String action,String address){try{Intent i=new Intent(this,TapeService.class).setAction(action);if(address!=null)i.putExtra("address",address);startForegroundService(i);}catch(Exception e){Toast.makeText(this,"操作失败："+e.getMessage(),Toast.LENGTH_LONG).show();}}
 private void scan(){BluetoothManager manager=getSystemService(BluetoothManager.class);BluetoothAdapter adapter=manager.getAdapter();if(adapter==null){Toast.makeText(this,"此手机不支持蓝牙，仍可使用手机录音",Toast.LENGTH_LONG).show();return;}if(!adapter.isEnabled()){startActivityForResult(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE),11);return;}stopScan();devices.clear();labels.clear();scanAdapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,labels);scanDialog=new AlertDialog.Builder(this).setTitle("选择你的灵感磁带").setMessage("请保持设备在录音待机；首次连接按设备屏幕上的配对码完成手机配对。").setNegativeButton("取消",(d,w)->stopScan()).create();
  ListView items=new ListView(this);items.setAdapter(scanAdapter);items.setOnItemClickListener((parent,v,pos,id)->{String address=devices.get(pos).getAddress();stopScan();scanDialog.dismiss();service(TapeService.CONNECT,address);});scanDialog.setView(items);scanDialog.setOnDismissListener(d->stopScan());scanDialog.show();scanner=adapter.getBluetoothLeScanner();ScanFilter filter=new ScanFilter.Builder().setServiceUuid(new ParcelUuid(UUID.fromString(Wire.SERVICE))).build();scanner.startScan(Collections.singletonList(filter),new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scanCallback);handler.postDelayed(()->{stopScan();if(devices.isEmpty()&&scanDialog!=null&&scanDialog.isShowing())scanDialog.setMessage("没有找到设备。请确认已安装手机同步版固件、设备处于录音待机，再点连接重试。");},12000);}
 private final ScanCallback scanCallback=new ScanCallback(){public void onScanResult(int type,ScanResult result){runOnUiThread(()->{String name=result.getScanRecord()==null?null:result.getScanRecord().getDeviceName();if(!"iDea Tape".equals(name))return;BluetoothDevice dev=result.getDevice();for(BluetoothDevice d:devices)if(d.getAddress().equals(dev.getAddress()))return;devices.add(dev);labels.add("iDea Tape  ·  "+dev.getAddress());scanAdapter.notifyDataSetChanged();});}public void onScanFailed(int code){runOnUiThread(()->Toast.makeText(MainActivity.this,"蓝牙搜索失败，请稍后重试",Toast.LENGTH_LONG).show());}};
 private void stopScan(){if(scanner!=null){try{scanner.stopScan(scanCallback);}catch(Exception ignored){}scanner=null;}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==11&&result==RESULT_OK)scan();}
 private Uri uri(String name){return Uri.parse("content://cn.ideatape.recorder.share/"+name);}
 private void share(String key,boolean hasLocation){String[] options=hasLocation?new String[]{"仅分享音频","分享音频及位置资料"}:new String[]{"分享音频"};new AlertDialog.Builder(this).setTitle("分享录音").setItems(options,(d,index)->{Intent send;if(index==1){ArrayList<Uri> files=new ArrayList<>();files.add(uri(key+".wav"));files.add(uri(key+".json"));send=new Intent(Intent.ACTION_SEND_MULTIPLE).setType("*/*").putParcelableArrayListExtra(Intent.EXTRA_STREAM,files);send.setClipData(ClipData.newRawUri("audio",files.get(0)));send.getClipData().addItem(new ClipData.Item(files.get(1)));}else{Uri wav=uri(key+".wav");send=new Intent(Intent.ACTION_SEND).setType("audio/wav").putExtra(Intent.EXTRA_STREAM,wav);send.setClipData(ClipData.newRawUri("audio",wav));}send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"分享灵感"));}).show();}

 private void toggleFavorites(){favoritesOnly=!favoritesOnly;applySnapshot();}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("page",page);b.putString("query",query);b.putBoolean("favorites",favoritesOnly);b.putLong("from",dateFrom);b.putLong("until",dateUntil);b.putString("dateLabel",dateLabel);}
 public void onBackPressed(){if(page==3)navigate(returnPage);else if(page!=0)navigate(0);else super.onBackPressed();}
 protected void onResume(){super.onResume();if(map!=null)map.resume();rendered=-1;handler.removeCallbacks(refresh);handler.post(refresh);}
 protected void onPause(){handler.removeCallbacks(holdSpeed);if(holdingSpeed){holdingSpeed=false;applySpeed(playbackSpeed);}tape.state(false,false);if(playerTape!=null)playerTape.state(false,false);if(map!=null)map.pause();handler.removeCallbacks(refresh);stopScan();super.onPause();}
 public void onLowMemory(){super.onLowMemory();if(map!=null)map.lowMemory();}
 protected void onDestroy(){finishPendingDelete();destroyed=true;handler.removeCallbacksAndMessages(null);if(player!=null)player.release();if(map!=null)map.close();files.shutdown();super.onDestroy();}
